// Relative imports are not allowed inside an ambient module, so types come in
// through the `@/` alias.

/** Everything the injected routes read, generated by the integration. */
declare module "virtual:astronaut-cms/server" {
  import type { CmsClientConfig, CmsServerConfig } from "@/integration/types";
  import type { ComponentSchemaMap } from "@/shared/field-schema";

  export const client: CmsClientConfig;
  export const server: CmsServerConfig;
  export const components: ComponentSchemaMap;
}

/** What only resolves in the runtime the injected routes run in. */
declare module "virtual:astronaut-cms/runtime" {
  import type { LocalStorage as LocalStorageClass } from "@/server/storage/local";

  /** The Workers `env`, where the injected routes run in Workers. Only bindings are read off it. */
  export const env: Record<string, unknown> | undefined;
  /** The filesystem backend, or null in any build that is not the dev API. */
  export const LocalStorage: typeof LocalStorageClass | null;
}

declare module "virtual:astronaut-cms/assets" {
  import type { ImageMetadata } from "astro";
  import type { MediaRefConfig } from "@/shared/media";

  export const media: MediaRefConfig;
  /** Lazy asset loader maps, keyed by root-absolute path. */
  export const images: Record<string, () => Promise<ImageMetadata>>;
  export const files: Record<string, () => Promise<string>>;
  /** Whether the maps hold only content-referenced assets (a build) or the whole media directory (dev). */
  export const referencedOnly: boolean;
}

/** The collections whose `sort` is not astro's own, and the file order of those sorted by file. */
declare module "virtual:astronaut-cms/order" {
  import type { CollectionSort } from "@/shared/types";

  export const sorts: Record<string, CollectionSort>;
  export const fileOrder: Record<string, string[]>;
}

/** The site's components, lowered in the admin, where `icon` and `editor` are live. */
declare module "virtual:astronaut-cms/user-config" {
  import type { ComponentManifest } from "@/internal/user-config";

  export const components: ComponentManifest;
}
